-- READ-ONLY six-archive cohort summary; SELECT only.
SELECT 'eu_old' AS archive,7 AS gap_count,COUNT(DISTINCT gap_id) AS gaps_with_rows,7-COUNT(DISTINCT gap_id) AS gaps_without_rows,COUNT(*) AS source_rows,COUNT(DISTINCT CASE WHEN `outTemp` IS NOT NULL THEN gap_id END) AS gaps_with_outTemp, SUM(`outTemp` IS NOT NULL) AS values_outTemp, COUNT(DISTINCT CASE WHEN `outHumidity` IS NOT NULL THEN gap_id END) AS gaps_with_outHumidity, SUM(`outHumidity` IS NOT NULL) AS values_outHumidity, COUNT(DISTINCT CASE WHEN `rain` IS NOT NULL THEN gap_id END) AS gaps_with_rain, SUM(`rain` IS NOT NULL) AS values_rain, COUNT(DISTINCT CASE WHEN `rainRate` IS NOT NULL THEN gap_id END) AS gaps_with_rainRate, SUM(`rainRate` IS NOT NULL) AS values_rainRate, COUNT(DISTINCT CASE WHEN `windSpeed` IS NOT NULL THEN gap_id END) AS gaps_with_windSpeed, SUM(`windSpeed` IS NOT NULL) AS values_windSpeed, COUNT(DISTINCT CASE WHEN `windGust` IS NOT NULL THEN gap_id END) AS gaps_with_windGust, SUM(`windGust` IS NOT NULL) AS values_windGust, COUNT(DISTINCT CASE WHEN `barometer` IS NOT NULL THEN gap_id END) AS gaps_with_barometer, SUM(`barometer` IS NOT NULL) AS values_barometer FROM (SELECT CASE WHEN `dateTime`>1705083000 AND `dateTime`<1705140600 THEN 1 WHEN `dateTime`>1714124700 AND `dateTime`<1714128900 THEN 2 WHEN `dateTime`>1716036300 AND `dateTime`<1716041400 THEN 3 WHEN `dateTime`>1716144900 AND `dateTime`<1716150000 THEN 4 WHEN `dateTime`>1726394700 AND `dateTime`<1726401900 THEN 5 WHEN `dateTime`>1726575300 AND `dateTime`<1726579800 THEN 6 WHEN `dateTime`>1727676300 AND `dateTime`<1727693400 THEN 7 ELSE NULL END AS gap_id,`dateTime`,`outTemp`,`outHumidity`,`rain`,`rainRate`,`windSpeed`,`windGust`,`barometer` FROM `pocasi-loucka.eu_old`.`archive` WHERE (`dateTime`>1705083000 AND `dateTime`<1705140600) OR (`dateTime`>1714124700 AND `dateTime`<1714128900) OR (`dateTime`>1716036300 AND `dateTime`<1716041400) OR (`dateTime`>1716144900 AND `dateTime`<1716150000) OR (`dateTime`>1726394700 AND `dateTime`<1726401900) OR (`dateTime`>1726575300 AND `dateTime`<1726579800) OR (`dateTime`>1727676300 AND `dateTime`<1727693400)) q;
